details:
I have two behaviours
An intractable that locally calls SetOwner for itself, and calls SetOwner for another gameObject on the owner side via OnOwnershipRequest (and an IsOwner Check)
The second behaviours can only be transferred via the owner.
When checking the logs, I can see that otherObject is transferred, but also is rejected.
Despite this, both objects are successfully transferred to the player that used the interact
See the following for an U# code for both
```
using UdonSharp;
using UnityEngine;
using VRC.SDKBase;
using VRC.Udon;
public class OnReqTest : UdonSharpBehaviour
{
    public GameObject otherObject;
    public override void Interact()
    {
        if (!Networking.IsOwner(gameObject))
            Networking.SetOwner(Networking.LocalPlayer, gameObject);
    }
    public override bool OnOwnershipRequest(VRCPlayerApi requestingPlayer, VRCPlayerApi requestedOwner)
    {
        Debug.Log("Interact Object Owner: " + Networking.GetOwner(gameObject).displayName + ", ReqPlayer: " + requestingPlayer.displayName + ", NewOwner: " + requestedOwner.displayName);
        if (Networking.IsOwner(gameObject))
        {
            Debug.Log("Giving Requested Owner an extra object to own");
            Networking.SetOwner(requestedOwner, otherObject);
        }
        return true;
    }
}
```
And the following for the otherObject
```
using UdonSharp;
using UnityEngine;
using VRC.SDKBase;
using VRC.Udon;
public class TestUsing : UdonSharpBehaviour
{
    public override bool OnOwnershipRequest(VRCPlayerApi requestingPlayer, VRCPlayerApi requestedOwner)
    {
        Debug.Log("Owner: " + Networking.GetOwner(gameObject).displayName + ", ReqPlayer: " + requestingPlayer.displayName + ", NewOwner: " + requestedOwner.displayName);
        Debug.Log(requestingPlayer == Networking.GetOwner(gameObject));
        return requestingPlayer == Networking.GetOwner(gameObject);
    }
}
```
